/* Configurable draft. Lottery and selections are persisted independently of the calendar. */
let draftTab='board',draftSearch='',draftPosition='all',draftSchool='all';
function ensureDraft(){
 if(state.draft?.year===state.year)return state.draft;
 const rules=leagueRules(),rounds=rules.draftRounds,poolSize=draftPoolSize(state.teams.length,rounds);
 const prospects=Array.from({length:poolSize},(_,i)=>{
 const id=2000000+(state.year-1900)*500+i,p=player(id,i,-10,state.leagueGender||'male','draft');p.age=rand(rules.prospectAgeMin,rules.prospectAgeMax);internationalDraftPathway(p);p.salary=wnbaEnabled()?wnbaMillions(wnbaMinimum(p,state.year+1)):1;p.ovr=Math.min(82,Math.max(50,p.ovr));p.pot=Math.min(99,p.ovr+rand(8,23));p.ovr=ratingLimit(p.ovr+leagueRules().draftStrength);p.pot=Math.max(p.ovr,ratingLimit(p.pot+leagueRules().draftStrength));p.attributes=generatedAttributes(p);p.tendencies=generatedTendencies(p,p.attributes);ensurePlayerArchetype(p,state.year,true);p.bio=generatePlayerBio(p,state.year,state.teams,true);return p});
 return state.draft={year:state.year,rounds,poolSize,order:[],picks:[],prospects};
}
function draftReady(){return state.champion!==null&&state.day>=seasonLength()}
function draftComplete(){return state.draft?.year===state.year&&state.draft.picks.length===state.teams.length*draftRoundCount()}
async function draftCommit(before){if(await save()===false){state=before;toast('Could not save draft changes. Please try again.');render();return false}render();return true}
// Weighted draws without replacement: each draw picks a remaining team with probability weight / remaining total.
// Winners are removed from `eligible`.
function lotteryDraw(eligible,draws,random=Math.random){const won=[];for(let n=0;n<draws&&eligible.length;n++){let roll=random()*eligible.reduce((s,t)=>s+t.weight,0),at=eligible.findIndex(t=>(roll-=t.weight)<0);won.push(eligible.splice(at<0?eligible.length-1:at,1)[0].id)}return won}
// Exact odds of each team (by position in `weights`) landing each pick: odds[team][slot], slots 0..draws-1 drawn, then
// the rest in order. Used to check the drawing against the configured system.
function lotteryOdds(weights,draws){const n=weights.length,odds=weights.map(()=>Array(n).fill(0));
 const walk=(left,slot,p)=>{if(slot===draws||!left.length){left.forEach((t,i)=>odds[t][slot+i]+=p);return}const total=left.reduce((s,t)=>s+weights[t],0);if(total<=0){left.forEach((t,i)=>odds[t][slot+i]+=p);return}for(const t of left)if(weights[t]>0){const q=p*weights[t]/total;odds[t][slot]+=q;walk(left.filter(x=>x!==t),slot+1,q)}};
 walk(weights.map((_,i)=>i),0,1);return odds}
async function runDraftLottery(){if(state.expansion?.active)return toast('Finish or cancel the expansion draft before running the lottery.');if(!gmCanAdvance()||!draftReady())return toast('Finish the playoffs before the lottery.');const before=snapshotState(),d=ensureDraft();if(d.order.length)return;
 const expansion=state.expansion?.history.find(h=>h.year===state.year),ranked=rank().filter(t=>t.id!==expansion?.team),eligible=ranked.filter(t=>!ownerPlayoffClub(t)).reverse().map((t,i,a)=>({id:t.id,weight:a.length-i})),winners=[];
 const mode=leagueRules().lotteryMode;
 if(mode==='equal')eligible.forEach(t=>t.weight=1);
 if(expansion?.config.seed==='equal'){eligible.forEach(t=>t.weight=1);eligible.push({id:expansion.team,weight:1})}
 if(mode==='custom'){let weights;try{weights=parseLotteryChances(leagueRules().lotteryChances);if(weights.length<eligible.length||weights.slice(0,eligible.length).filter(w=>w>0).length<Math.min(leagueRules().lotterySelections,eligible.length))throw Error('Provide a weight for every lottery team and enough positive weights for the selected lottery slots.');}catch(e){state=before;return toast(e.message)}eligible.forEach((t,i)=>t.weight=weights[i]);}
 winners.push(...lotteryDraw(eligible,['record','random','snake'].includes(mode)?0:Math.min(leagueRules().lotterySelections,eligible.length)));
 d.order=[...winners,...eligible.map(t=>t.id),...ranked.filter(t=>ownerPlayoffClub(t)).reverse().map(t=>t.id)];
 if(mode==='random'){for(let i=d.order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[d.order[i],d.order[j]]=[d.order[j],d.order[i]];}}
 if(expansion&&expansion.config.seed!=='equal')d.order.splice(expansion.config.seed==='first'?0:3,0,expansion.team);
 d.type=mode;d.laterOrder=rank().slice().reverse().map(t=>t.id);
 say('Draft lottery complete. The first-round order is locked.');await draftCommit(before);
}
function draftOrder(d){return draftBaseOrder(d)}
function draftScore(p,club){const at=club.roster.filter(x=>x.pos===p.pos),need=at.length?80-Math.max(...at.map(x=>x.ovr)):20;return p.ovr*.55+p.pot*.45+need*.2}
function draftPickInternal(id){if(wnbaEnabled())return wnbaDraftPick(id);const d=ensureDraft(),index=d.picks.length;if(!draftReady()||!d.order.length||index>=state.teams.length*draftRoundCount())return false;
 const club=state.teams[draftOrder(d)[index]],at=d.prospects.findIndex(p=>p.id===id);if(at<0)return false;
 const p=d.prospects.splice(at,1)[0],round=Math.floor(index/state.teams.length)+1;p.salary=rookieContractSalary(index,round,draftRoundCount(d));p.contractThrough=state.year+rookieContractYears(round);p.rotationMinutes=0;p.tradeWait=15;
 // Biography records the overall pick across all configured rounds.
 Object.assign(p.bio,{draftYear:state.year,draftRound:round,draftPick:index+1,draftTeam:club.abbr,debutYear:state.year});
 d.picks.push({number:index+1,round,team:club.id,id:p.id,name:p.name,pos:p.pos,ovr:p.ovr,pot:p.pot});
 const stashed=internationalOnDraft(p);if(!stashed)draftMakeRoom(club,p,round);
 if(!stashed&&club.roster.length<rosterMaximum()&&ownerPayroll(club)+p.salary<=financeRosterLimit(club)+.001){internationalPrepareSigning(p);club.roster.push(p)}else(state.draftRights??=[]).push({team:club.id,player:p});
 say(club.city+' selects '+p.name+' with pick '+(index+1)+'.');return true;
}
async function selectDraftPlayer(id){const d=ensureDraft();if(!ownerCanManage()||draftOrder(d)[d.picks.length]!==controlledTeamId())return;const before=snapshotState();if(draftPickInternal(id))await draftCommit(before)}
async function autoDraft(untilUser=false){if(!gmCanAdvance()||!draftReady())return;const d=ensureDraft();if(!d.order.length)return toast('Run the draft lottery first.');const before=snapshotState();let count=0;
 while(d.picks.length<state.teams.length*draftRoundCount()){const club=state.teams[draftOrder(d)[d.picks.length]];if(untilUser&&club.id===controlledTeamId())break;const p=[...d.prospects].sort((a,b)=>draftScore(b,club)-draftScore(a,club))[0];if(!p||!draftPickInternal(p.id))break;count++}if(count)await draftCommit(before);
}
async function signDraftRights(id){if(wnbaEnabled())return wnbaSignRights(id);const rights=state.draftRights||[],r=rights.find(r=>r.player.id===id&&r.team===controlledTeamId());if(!ownerCanManage()||!r)return;if(!internationalStashReady(r.player))return toast('This player is under an overseas commitment until '+r.player.international.stashUntil+'.');if(team().roster.length>=rosterMaximum())return toast('Make roster space before signing this rookie.');const signingSalary=r.player.international?.stashUntil?rookieContractSalary(r.player.bio.draftPick-1,r.player.bio.draftRound,Math.max(r.player.bio.draftRound,draftRoundCount())):r.player.salary;if(ownerPayroll(team())+signingSalary>financeRosterLimit()+.001)return toast('Make payroll room before signing this rookie.');const before=snapshotState();internationalPrepareSigning(r.player);r.player.contractThrough=state.year+rookieContractYears(r.player.bio.draftRound);r.player.tradeWait=15;team().roster.push(r.player);state.draftRights=rights.filter(x=>x!==r);await draftCommit(before)}
const draftNewSeasonBefore=newSeason;
newSeason=function(){if(!draftComplete()){go('Draft');return toast('Complete the draft lottery and draft before starting next season.')}state.draftHistory??=[];if(!state.draftHistory.some(x=>x.year===state.year))state.draftHistory.push({year:state.year,teamCount:state.teams.length,rounds:draftRoundCount(),picks:copy(state.draft.picks)});const year=state.year,completed=state.draft;state.draft=null;const result=draftNewSeasonBefore();if(state.year===year)state.draft=completed;return result};
const draftPhaseBefore=seasonPhaseLabel;
seasonPhaseLabel=function(){return draftReady()?draftComplete()?'Offseason':state.draft?.order.length?'Draft':'Draft Lottery':draftPhaseBefore()};
function draftSwitch(tab){draftTab=tab;render()}
function draftFilter(key,value){if(key==='search')draftSearch=value;if(key==='position')draftPosition=value;if(key==='school')draftSchool=value;render()}
function draftReport(id){const p=ensureDraft().prospects.find(x=>x.id===id);if(!p)return;const dialog=document.getElementById('profile');dialog.className='player-dialog player-fullscreen';dialog.innerHTML=`<button class="pp-close" onclick="document.getElementById('profile').close()" aria-label="Close scouting report">×</button><header class="pp-header"><div class="pp-portrait">${playerSilhouette()}</div><div><div class="eyebrow">DRAFT SCOUTING REPORT</div><h1>${escapeHTML(p.name)}</h1><p>${p.pos} · Age ${p.age} · ${escapeHTML(p.bio.college)}</p><p>${Math.floor(p.bio.heightInches/12)}′ ${p.bio.heightInches%12}″ · ${p.bio.weightLbs} lbs · ${escapeHTML(p.bio.hometown)}</p><p>Scouted rating ${ratingMarkup(coachScoutedRating(p,'lay'))} finishing · Potential ${ratingMarkup(financeScoutedPotential(p).estimate)}</p></div></header><div class="pp-content">${internationalPlayerInfo(p)}${playerAttributes({p,club:null,own:false})}</div>`;dialog.showModal()}
function draftPicksTable(picks){return `<div class="tablewrap"><table><thead><tr><th>Pick</th><th>Team</th><th>Player</th><th>Pos</th><th>Round</th></tr></thead><tbody>${picks.map(p=>`<tr><td>${p.number}</td><td><span class="po-stat-team">${secondaryTeamLogo(state.teams[p.team])}${escapeHTML(state.teams[p.team].abbr)}</span></td><td>${escapeHTML(p.name)}</td><td>${p.pos}</td><td>${p.round}</td></tr>`).join('')}</tbody></table></div>`}
function draftNeeds(){return ['PG','SG','SF','PF','C'].map(pos=>{const players=team().roster.filter(p=>p.pos===pos);return `<div class="draft-need"><strong>${pos}</strong><span>${players.length} players</span><b>${players.length?ratingMarkup(Math.max(...players.map(p=>p.ovr))):'Open'}</b></div>`}).join('')}
function draftView(){const d=ensureDraft(),order=d.order.length?draftOrder(d):[],current=order[d.picks.length],next=order.findIndex((t,i)=>t===controlledTeamId()&&i>=d.picks.length),finished=draftComplete(),active=draftReady()&&d.order.length&&!finished;
 const prospects=[...d.prospects].sort((a,b)=>draftScore(b,team())-draftScore(a,team())),schools=[...new Set(d.prospects.map(p=>p.bio.college))].sort();const shown=prospects.filter(p=>(draftPosition==='all'||p.pos===draftPosition)&&(draftSchool==='all'||p.bio.college===draftSchool)&&p.name.toLowerCase().includes(draftSearch.toLowerCase()));
 const board=`<section class="po-panel"><h2>TOP PROSPECTS <small class="muted">${shown.length} available</small></h2><div class="draft-filters"><input aria-label="Search prospects" placeholder="Search prospects…" value="${escapeHTML(draftSearch)}" onchange="draftFilter('search',this.value)"><select aria-label="Position" onchange="draftFilter('position',this.value)">${['all','PG','SG','SF','PF','C'].map(x=>`<option ${draftPosition===x?'selected':''} value="${x}">${x==='all'?'All positions':x}</option>`).join('')}</select><select aria-label="College or development program" onchange="draftFilter('school',this.value)"><option value="all">All colleges / programs</option>${schools.map(x=>`<option ${draftSchool===x?'selected':''}>${escapeHTML(x)}</option>`).join('')}</select></div><div class="tablewrap"><table><thead><tr><th>#</th><th>Player</th><th>Pos</th><th>HT</th><th>WT</th><th>Age</th><th>College / Program</th><th>Scout POT</th><th>Actions</th></tr></thead><tbody>${shown.map((p,i)=>`<tr><td>${i+1}</td><td><button class="namebutton" onclick="draftReport(${p.id})">${escapeHTML(p.name)}</button>${p.international?`<small>${escapeHTML(INTERNATIONAL_COUNTRIES[p.international.country].name)} · ${INTERNATIONAL_PATHWAYS[p.international.pathway]}</small>`:''}</td><td>${p.pos}</td><td>${Math.floor(p.bio.heightInches/12)}′${p.bio.heightInches%12}″</td><td>${p.bio.weightLbs}</td><td>${p.age}</td><td>${escapeHTML(p.bio.college)}</td><td>${ratingMarkup(financeScoutedPotential(p).estimate)}</td><td><button onclick="draftReport(${p.id})">View</button> ${active&&current===controlledTeamId()?`<button class="primary" onclick="selectDraftPlayer(${p.id})">Draft</button>`:''}</td></tr>`).join('')}</tbody></table></div><p class="muted">Potential estimates reflect your scouting budget. Rookie contracts by round: ${Array.from({length:draftRoundCount(d)},(_,i)=>rookieContractYears(i+1)).join(' / ')} seasons. Full rosters retain unsigned draft rights.</p></section>`;
 return `<div class="playoffs-page draft-page">${pageHeaderFor('Draft')}<nav class="po-tabs" aria-label="Draft views">${[['board','Draft board'],['picks','Your picks'],['big','Big board'],['needs','Team needs'],['history','Draft history']].map(([key,label])=>`<button class="${draftTab===key?'selected':''}" aria-pressed="${draftTab===key}" onclick="draftSwitch('${key}')">${label}</button>`).join('')}</nav><div class="draft-info"><section class="po-panel"><h2>DRAFT INFORMATION</h2><div class="draft-facts"><div><small>STATUS</small><strong>${!draftReady()?'After playoffs':finished?'Complete':d.order.length?'On the clock':'Lottery pending'}</strong></div><div><small>ROUNDS</small><strong>${draftRoundCount(d)}</strong></div><div><small>TEAMS</small><strong>${state.teams.length}</strong></div><div><small>SELECTIONS</small><strong>${d.picks.length} / ${state.teams.length*draftRoundCount()}</strong></div></div><div class="draft-actions">${!draftReady()?'<p>Finish the playoffs, then run the lottery to unlock the draft.</p>':!d.order.length?'<button class="primary" onclick="watchDraftLottery()">Watch lottery</button><button onclick="runDraftLottery()">Run draft lottery</button>':finished?'<button class="primary" onclick="newSeason()">Continue to free agency →</button>':`<button class="primary" onclick="autoDraft(true)" ${current===controlledTeamId()?'disabled':''}>Advance to your pick</button><button onclick="autoDraft(false)">Auto-draft remaining picks</button>`}</div>${d.order.length?'<button onclick="watchDraftLottery()">Watch lottery results</button>':''}<small class="muted">${draftLotteryDescription()} Expansion seeding rules still apply. No real-time clock.</small></section><section class="po-panel"><h2>YOUR NEXT PICK</h2><div class="po-stat-team">${teamLogo(team())}<strong>${escapeHTML(team().city+' '+team().name)}</strong></div><p>${!d.order.length?'Awaiting lottery':next<0?'All selections complete':'Round '+(Math.floor(next/state.teams.length)+1)+' · Pick '+(next+1)}</p>${active?`<small>On the clock: ${escapeHTML(state.teams[current].city)} · #${d.picks.length+1}</small>`:''}</section></div>${draftTab==='needs'?`<section class="po-panel"><h2>POSITIONAL DEPTH</h2>${draftNeeds()}</section>`:draftTab==='history'?`<section class="po-panel"><h2>DRAFT HISTORY</h2>${[...(state.draftHistory||[]),...(d.picks.length?[{year:state.year,picks:d.picks}]:[])].reverse().map(h=>`<h3>${h.year}</h3>${draftPicksTable(h.picks)}`).join('')||'<p>No draft selections yet.</p>'}</section>`:draftTab==='picks'?`<section class="po-panel"><h2>YOUR PICKS</h2>${draftPicksTable(d.picks.filter(p=>p.team===controlledTeamId()))}${(state.draftRights||[]).filter(r=>r.team===controlledTeamId()).map(internationalDraftRightsRow).join('')}</section>`:`${draftTab==='board'?`<div class="draft-info"><section class="po-panel"><h2>DRAFT BOARD</h2>${d.order.length?draftPicksTable(order.map((team,i)=>d.picks[i]||{number:i+1,round:Math.floor(i/state.teams.length)+1,team,name:i===d.picks.length?'On the clock':'Awaiting selection',pos:'—'})):'<p>Order becomes available after the lottery.</p>'}</section><section class="po-panel"><h2>TEAM NEEDS</h2>${draftNeeds()}</section></div>`:''}${board}`}</div>`;
}
function readDraftData(raw,readPlayer,bad,count,year){
 const roundsOf=d=>{const n=d.rounds??2;if(!Number.isInteger(n)||n<1||n>5)bad('invalid draft rounds');return n};
 const ids=rows=>Array.isArray(rows)&&rows.length===count&&new Set(rows).size===count&&rows.every(id=>Number.isInteger(id)&&id>=0&&id<count);
 const picks=(rows,teamCount=count,rounds=2)=>{if(!Number.isInteger(teamCount)||teamCount<2||teamCount>count||!Array.isArray(rows)||rows.length>teamCount*rounds)bad('invalid draft picks');return rows.map((p,i)=>{if(p.number!==i+1||p.round!==Math.floor(i/teamCount)+1||!Number.isInteger(p.team)||p.team<0||p.team>=count||!Number.isInteger(p.id)||typeof p.name!=='string'||p.name.length>80||!['PG','SG','SF','PF','C'].includes(p.pos))bad('invalid draft selection');return {...p}})};
 let draft=null;if(raw.draft){const d=raw.draft,rounds=roundsOf(d),poolSize=d.poolSize??Math.max(40,count*3);if(d.year!==year||!Array.isArray(d.order)||!(d.order.length===0||ids(d.order))||!Array.isArray(d.prospects)||d.prospects.length>216||poolSize!==(d.poolSize===undefined?Math.max(40,count*3):draftPoolSize(count,rounds))||d.laterOrder!==undefined&&!ids(d.laterOrder)||d.type!==undefined&&!['weighted','equal','custom','record','random','snake'].includes(d.type))bad('invalid draft');draft={year,rounds,poolSize,order:[...d.order],picks:picks(d.picks,count,rounds),prospects:d.prospects.map(readPlayer),...(d.laterOrder?{laterOrder:[...d.laterOrder]}:{}),...(d.type?{type:d.type}:{})};if(draft.prospects.length+draft.picks.length!==poolSize||new Set([...draft.picks,...draft.prospects].map(p=>p.id)).size!==poolSize)bad('invalid draft pool');if(draft.picks.length&&!draft.order.length||draft.order.length&&raw.champion===null)bad('invalid draft progress');const order=Array.from({length:rounds},(_,r)=>r===0?draft.order:d.type==='snake'?(r%2?[...draft.order].reverse():draft.order):d.laterOrder||[]).flat();if(draft.picks.some((p,i)=>order[i]!==undefined&&p.team!==((raw.tradePickOwners||[]).find(x=>x.year===year&&x.origin===order[i]&&x.round===p.round)?.owner??order[i])))bad('invalid draft ownership');}
 const rights=raw.draftRights||[],history=raw.draftHistory||[];if(!Array.isArray(rights)||rights.length>2000||!Array.isArray(history)||history.length>8101)bad('invalid draft history');return {draft,draftRights:rights.map(r=>{if(!Number.isInteger(r.team)||r.team<0||r.team>=count)bad('invalid draft rights');return {team:r.team,player:readPlayer(r.player)}}),draftHistory:history.map(h=>{if(!Number.isInteger(h.year)||h.year<1900||h.year>year)bad('invalid draft year');const rounds=roundsOf(h),teamCount=h.teamCount||h.picks.length/rounds;return {year:h.year,picks:picks(h.picks,teamCount,rounds),teamCount,rounds}})};
}
